from lib import *
S = SS('p67')
steps = [
    step("8 个 worker 进程各自处理同一批 3000 个 URL(顺序相同,让重复尽量多),“新”URL 算抓一次。先 SISMEMBER 再 SADD:3 次实验抓取次数是 17472、16433、18098(3000 个不同 URL,平均每个被抓了五六次);只用 SADD 的返回值(1 表示新加入):3 次都是 3000。检查和加入是两条命令,中间别的 worker 也可以通过检查;SADD 本身是原子的,返回值就是“我是第一个”的凭据。这个实验里 worker 步调一致,是重复最多的情形。", t=tl(S(1)), done=lidx(S(1), '只用 SADD 的返回值'), mark=lidx(S(1), '先 SISMEMBER 再 SADD'), b=bars([['先查再加:抓取次数(最大)', 18098, '18098'], ['只用 SADD 返回值:抓取次数', 3000, '3000'], ['不同 URL 数', 3000, '3000']], 19000, mark=[0], done=[1, 2]), kv=KV([['先 SISMEMBER 再 SADD', '16433–18098 次'], ['只用 SADD 返回值', '3000 次(没有重复)'], ['不同 URL', '3000 个']], ['只用 SADD 返回值'])),
    step("同样 30 万个 URL(平均 64 字节)用不同结构保存,Redis 8.10.2 的 used_memory 增量:SET 存完整 URL 30.5 MiB(平均每个 106.5 字节,编码 hashtable);SET 存 8 字节摘要 12.2 MiB(42.5 字节);SET 存 16 字节 md5 16.7 MiB(58.5 字节);位图 Bloom(每个元素 9.6 位、7 个哈希)0.6 MiB(1.9 字节),对 10 万个没加入过的 URL 查询误判 1.06%;HyperLogLog 约 0.0 MiB,PFCOUNT 299568(真实 30 万,误差 0.14%),但只能数个数、不能判断见没见过。8 字节摘要出现碰撞的概率约 n²/2^65 = 2.4e-09(算出来的,没实测)。", t=tl(S(2)), done=lidx(S(2), '位图 Bloom'), mark=lidx(S(2), 'SET:完整 URL 字符串'), b=bars([['SET 完整 URL MiB', 30.5, '30.5'], ['SET 8 字节摘要 MiB', 12.2, '12.2'], ['SET md5 MiB', 16.7, '16.7'], ['Bloom 位图 MiB', 0.6, '0.6']], 31, mark=[0], done=[3]), kv=KV([['完整 URL', '106.5 字节/个'], ['8 字节摘要', '42.5 字节/个'], ['Bloom(误判 1.06%)', '1.9 字节/个']], ['Bloom(误判 1.06%)'])),
    step("往 SET 里加 20 万个 URL 的吞吐(每种 3 次取中位数):一次往返一个 SADD 22109 个/秒(21431–22462,只跑了 2 万个);pipeline 每批 100 个 185879(181536–198964);pipeline 每批 1000 个 262806(262218–262929);一条 SADD 带 1000 个成员 820929(791220–871517)。pipeline 能保留每个 SADD 的返回值(知道哪些是新的);一条 SADD 多成员更快,但只返回新加入的个数,不知道是哪几个。", t=tl(S(3)), done=lidx(S(3), 'pipeline,每批 100'), mark=lidx(S(3), '逐个 SADD'), b=bars([['逐个 SADD', 22109, '22109'], ['pipeline 100', 185879, '185879'], ['pipeline 1000', 262806, '262806'], ['一条 SADD 1000 成员', 820929, '820929']], 830000, mark=[0], done=[1, 2]), kv=KV([['逐个 SADD', '约 2.2 万个/秒'], ['pipeline(保留每个返回值)', '18.6–26.3 万个/秒'], ['一条 SADD 多成员', '82 万个/秒,只给总数']], ['pipeline(保留每个返回值)'])),
    step("Bloom 过滤器同样要原子。8 个 worker 处理同一批 3000 个 URL,位图 2^24 位:先逐个 GETBIT 检查、没见过再 SETBIT:3 次抓取次数 9590、9713、9688;在 MULTI/EXEC 里对 7 个位置 SETBIT、用返回的旧值判断(旧值全是 1 才算见过):3 次都是 3000。Bloom 的“检查”和“置位”也不能分开;SETBIT 返回旧值,正好合成一次原子的“测试并置位”。", t=tl(S(4)), done=lidx(S(4), '在 MULTI/EXEC 里'), mark=lidx(S(4), '先 GETBIT'), b=bars([['先检查再置位:抓取次数(最大)', 9713, '9713'], ['MULTI/EXEC 内 SETBIT:抓取次数', 3000, '3000']], 10000, mark=[0], done=[1]), kv=KV([['先 GETBIT 再 SETBIT', '9590–9713 次'], ['MULTI/EXEC 内 SETBIT 看旧值', '3000 次'], ['不同 URL', '3000 个']], ['MULTI/EXEC 内 SETBIT 看旧值'])),
    step("带过期时间的去重:连续 3 次 SET key NX EX 2 的返回是 [True, None, None](只有第一次拿到),等 2.2 秒再 SET NX 又返回 True(过期之后可以重抓)。10 万个 URL 每个一个带过期时间的 key(8 字节摘要作 key 名):平均每个 84 字节;全部放进一个 SET(8 字节摘要):平均每个 37 字节。需要“多久之内不重复抓”时用带 TTL 的 key,代价是内存约为 SET 的两倍多。", t=tl(S(5)), done=lidx(S(5), '连续 3 次 SET NX EX 2'), mark=lidx(S(5), '10 万个 URL'), b=bars([['每个 URL 一个带 TTL 的 key(字节/个)', 84, '84'], ['全部放进一个 SET(字节/个)', 37, '37']], 90, mark=[0], done=[1]), kv=KV([['SET NX EX 2', '第 1 次 True,之后 None,2.2 秒后 True'], ['带 TTL 的 key', '84 字节/个'], ['一个 SET', '37 字节/个']], ['带 TTL 的 key'])),
    step("很大的 SET(200 万个成员)删除:DEL 命令本身用了 242 ms,期间另一个连接每 1 ms 发一次 PING,最大延迟 242 ms(共 373 次,中位 0.11 ms);UNLINK 命令返回用了 0 ms,期间 PING 最大延迟 1 ms(共 377 次,中位 0.12 ms)。Redis 是单线程执行命令的,DEL 一个大 key 会让别的请求等它做完;UNLINK 把释放内存放到后台。去重集合会越长越大,清理时用 UNLINK,或者按域名、日期拆成多个小 key。", t=tl(S(6)), done=lidx(S(6), 'UNLINK:'), mark=lidx(S(6), 'DEL:'), b=bars([['DEL:PING 最大延迟 ms', 242, '242'], ['UNLINK:PING 最大延迟 ms', 1, '1']], 250, mark=[0], done=[1]), kv=KV([['DEL 200 万成员的 SET', '242 ms,PING 被挡 242 ms'], ['UNLINK', '0 ms 返回,PING 最大 1 ms'], ['做法', 'UNLINK,或拆成多个小 key']], ['UNLINK'])),
]
